const form = $('Interview Research Form').first().json;
const clearbitResponse = $input.all();

const companyName = (form['Company Name'] || '').trim();
let manualUrl = (form['Company Website URL (Optional)'] || '').trim();
const targetRole = (form['Target Role'] || 'General Candidate').trim();
const jobDescription = (form['Job Description (Optional)'] || 'Standard interview evaluation for this role.').trim();

let resolvedUrl = manualUrl;
let cleanDomain = '';
let urlSource = 'Manual Input';
let companyLogo = '';

if (!resolvedUrl) {
  try {
    const firstHit = clearbitResponse[0]?.json;
    const domainObj = Array.isArray(firstHit) ? firstHit[0] : firstHit;
    if (domainObj && domainObj.domain) {
      cleanDomain = domainObj.domain;
      resolvedUrl = 'https://' + cleanDomain;
      companyLogo = domainObj.logo || ('https://logo.clearbit.com/' + cleanDomain);
      urlSource = 'Auto-Discovered (' + cleanDomain + ')';
    }
  } catch (e) {}
}

if (!resolvedUrl) {
  const slug = companyName.toLowerCase().replace(/[^a-z0-9]/g, '');
  cleanDomain = slug + '.com';
  resolvedUrl = 'https://www.' + cleanDomain;
  companyLogo = 'https://logo.clearbit.com/' + cleanDomain;
  urlSource = 'Fallback Guess';
} else {
  if (!resolvedUrl.startsWith('http://') && !resolvedUrl.startsWith('https://')) {
    resolvedUrl = 'https://' + resolvedUrl;
  }
  cleanDomain = resolvedUrl.replace(/^https?:\/\/(www\.)?/, '').split('/')[0];
  if (!companyLogo) {
    companyLogo = 'https://logo.clearbit.com/' + cleanDomain;
  }
}

const websiteScreenshot = 'https://s.wordpress.com/mshots/v1/' + encodeURIComponent(resolvedUrl) + '?w=800';

return [{
  json: {
    company_name: companyName,
    company_domain: cleanDomain,
    company_url: resolvedUrl,
    url_resolution_mode: urlSource,
    company_logo: companyLogo,
    website_screenshot: websiteScreenshot,
    target_role: targetRole,
    job_description: jobDescription
  }
}];

const baseInput = $('Resolve URL and Visual Assets').first().json;

let websiteText = 'Official website scrape unavailable.';
try {
  const jinaItem = $('Scrape Website (Jina Reader)').first().json;
  const rawSite = typeof jinaItem === 'string' ? jinaItem : (jinaItem.data || JSON.stringify(jinaItem));
  websiteText = rawSite.substring(0, 8000);
} catch (e) {}

let newsList = [];
try {
  const rssItems = $('Fetch 6M News (Google RSS)').all();
  newsList = rssItems.slice(0, 8).map((item, idx) => 
    '[News #' + (idx + 1) + '] Title: ' + item.json.title + ' | Date: ' + (item.json.pubDate || 'Recent') + ' | Source URL: ' + (item.json.link || baseInput.company_url)
  );
} catch (e) {}

let hnList = [];
try {
  const hnData = $('Projects and Tech Pulse (HN API)').first().json;
  if (hnData && Array.isArray(hnData.hits)) {
    hnList = hnData.hits.map((h, idx) => 
      '[Tech Discussion #' + (idx + 1) + '] Title: ' + h.title + ' (Points: ' + h.points + ', Comments: ' + h.num_comments + ') | Article URL: ' + (h.url || baseInput.company_url) + ' | HN Thread: https://news.ycombinator.com/item?id=' + h.objectID
    );
  }
} catch (e) {}

return [{
  json: {
    ...baseInput,
    aggregated_research: {
      website_summary_markdown: '[Official Website Source: ' + baseInput.company_url + ']\n' + websiteText,
      recent_news_headlines: newsList.length ? newsList.join('\n') : 'No recent news headlines found.',
      community_tech_discussions: hnList.length ? hnList.join('\n') : 'No community discussions found.'
    }
  }
}];

parameters.text:
=You are an elite Executive Interview Strategist and Company Intelligence Researcher. Using both your deep internal knowledge of {{ $json.company_name }} and the live scraped intelligence provided below, create an exhaustive, visual Pre-Interview Research Dossier.

TARGET INTERVIEW DETAILS:
- Company: {{ $json.company_name }}
- Resolved Website: {{ $json.company_url }} ({{ $json.url_resolution_mode }})
- Target Role: {{ $json.target_role }}
- Job Description: {{ $json.job_description }}

LIVE SCRAPED INTELLIGENCE WITH SOURCE URLS:
1. Official Website Content:
{{ $json.aggregated_research.website_summary_markdown }}

2. Recent News (Last 6 Months):
{{ $json.aggregated_research.recent_news_headlines }}

3. Tech Community and Project Signals:
{{ $json.aggregated_research.community_tech_discussions }}

Return ONLY a raw, valid JSON object (no markdown formatting or code fences) matching this exact schema:
{
  "about_the_company": "Detailed overview of what the company does, its business model, revenue streams, target market, and competitive moat.",
  "mission_vision_and_values": "The company core mission statement, long-term vision, and cultural values, plus how candidates should align their answers.",
  "quantitative_ratings": {
    "market_momentum": 88,
    "engineering_complexity": 92,
    "innovation_velocity": 90,
    "product_moat": 85,
    "developer_brand": 87
  },
  "company_key_metrics": [
    {"label": "Primary Business Model", "value": "e.g. B2B SaaS / API Consumption"},
    {"label": "Core Tech Stack", "value": "e.g. Python, Go, React, Kubernetes"},
    {"label": "Market Segment", "value": "e.g. Enterprise FinTech / AI Infra"},
    {"label": "Interview Difficulty", "value": "e.g. High (System Design + Domain Depth)"}
  ],
  "mermaid_ecosystem_diagram": "graph LR\n  Users[Target Customers] --> Core[Core Platform]\n  Core --> ProdA[Primary Product]\n  Core --> ProdB[AI and Data Engine]\n  ProdA --> Stack[Cloud Infrastructure]",
  "flagship_projects_and_products": [
    "3 to 5 detailed bullet points covering their core products, major engineering initiatives, or flagship projects (cite [News #X] or [Tech Discussion #X] inline)."
  ],
  "recent_momentum_and_news": [
    "3 to 4 bullet points summarizing recent launches, funding, partnerships, or strategic shifts in the last 6-12 months (cite [News #X] inline)."
  ],
  "tech_stack_and_engineering_culture": "Inferred tech stack, architecture patterns, engineering velocity, and day-to-day working style.",
  "interview_talking_points_and_strategy": [
    "4 specific ways the candidate can pitch their background to solve immediate problems for the {{ $json.target_role }} position."
  ],
  "predicted_interview_questions": [
    "5 highly tailored technical, architectural, or behavioral questions the interviewer is likely to ask for this role."
  ],
  "reverse_interview_questions": [
    "4 sharp, insider-level questions the candidate should ask the interviewer about their projects, roadmap, or culture."
  ],
  "verified_evidence_log": [
    {
      "claim_or_topic": "Specific product launch, news event, or technical discussion",
      "source_title": "Headline or page title",
      "source_type": "Official Website | Google News | Hacker News",
      "evidence_date": "Publication date or Current",
      "source_url": "Exact https:// URL from the scraped intelligence"
    }
  ]
}

IMPORTANT FOR mermaid_ecosystem_diagram: Use simple graph LR syntax with alphanumeric node IDs and labels in square brackets like NodeA[Label Text] --> NodeB[Label Text]. Do NOT use parentheses or quotes inside square brackets.

parameters.jsCode:
const rawOutput = $input.first().json.text || $input.first().json.output || '{}';
const fenceRegex = new RegExp('\x60{3}(?:json)?', 'gi');
const cleanedJson = rawOutput.replace(fenceRegex, '').trim();
const baseInfo = $('Resolve URL and Visual Assets').first().json;

let dossier;
try {
  dossier = JSON.parse(cleanedJson);
} catch (e) {
  dossier = {
    about_the_company: cleanedJson,
    mission_vision_and_values: 'See company overview above.',
    quantitative_ratings: { market_momentum: 85, engineering_complexity: 85, innovation_velocity: 85, product_moat: 80, developer_brand: 85 },
    company_key_metrics: [],
    mermaid_ecosystem_diagram: 'graph LR\n  Users[Customers] --> Platform[Core Platform]\n  Platform --> AI[Products and Services]',
    flagship_projects_and_products: [],
    recent_momentum_and_news: [],
    tech_stack_and_engineering_culture: 'N/A',
    interview_talking_points_and_strategy: [],
    predicted_interview_questions: [],
    reverse_interview_questions: [],
    verified_evidence_log: []
  };
}

const O = '\u003c';
const C = '\u003e';
const tag = (name, attrs, body) => O + name + (attrs ? ' ' + attrs : '') + C + (body || '') + O + '/' + name + C;
const selfTag = (name, attrs) => O + name + (attrs ? ' ' + attrs : '') + C;
const renderList = (arr) => (Array.isArray(arr) ? arr.map(i => tag('li', 'style="margin-bottom:8px;"', i)).join('') : '');
const generatedDate = new Date().toISOString().split('T')[0];
const safeFileName = baseInfo.company_name.replace(/[^a-zA-Z0-9]/g, '_') + '_Visual_Interview_Dossier';

const r = dossier.quantitative_ratings || {};
const scores = [
  Number(r.market_momentum) || 85,
  Number(r.engineering_complexity) || 85,
  Number(r.innovation_velocity) || 85,
  Number(r.product_moat) || 80,
  Number(r.developer_brand) || 85
];
const chartConfig = {
  type: 'radar',
  data: {
    labels: ['Market Momentum', 'Eng Complexity', 'Innovation Speed', 'Product Moat', 'Tech Brand'],
    datasets: [{
      label: baseInfo.company_name + ' Benchmark (0-100)',
      data: scores,
      backgroundColor: 'rgba(79, 70, 229, 0.22)',
      borderColor: 'rgb(79, 70, 229)',
      pointBackgroundColor: 'rgb(79, 70, 229)',
      borderWidth: 2
    }]
  },
  options: {
    scale: { ticks: { beginAtZero: true, max: 100, stepSize: 20 } }
  }
};
const radarChartUrl = 'https://quickchart.io/chart?w=480&h=340&c=' + encodeURIComponent(JSON.stringify(chartConfig));

const rawMermaid = (dossier.mermaid_ecosystem_diagram || 'graph LR\n  A[Customer] --> B[' + baseInfo.company_name + ']\n  B --> C[Core Products]').trim();
const base64Mermaid = Buffer.from(rawMermaid, 'utf-8').toString('base64');
const mermaidImgUrl = 'https://mermaid.ink/svg/' + base64Mermaid;

const metricsHtml = (Array.isArray(dossier.company_key_metrics) ? dossier.company_key_metrics : []).map(m => 
  tag('div', 'style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:12px;"',
    tag('div', 'style="font-size:11px; text-transform:uppercase; color:#64748b; font-weight:700;"', m.label || '') +
    tag('div', 'style="font-size:14px; color:#0f172a; font-weight:600; margin-top:4px;"', m.value || '')
  )
).join('');

const scoreLabels = [
  { label: 'Market Momentum', val: scores[0] },
  { label: 'Engineering Complexity', val: scores[1] },
  { label: 'Innovation Velocity', val: scores[2] },
  { label: 'Competitive Product Moat', val: scores[3] },
  { label: 'Developer and Employer Brand', val: scores[4] }
];
const barsHtml = scoreLabels.map(s => 
  tag('div', 'style="margin-bottom:10px;"',
    tag('div', 'style="display:flex; justify-content:space-between; font-size:12px; font-weight:600; margin-bottom:4px;"',
      tag('span', '', s.label) + tag('span', '', s.val + ' / 100')
    ) +
    tag('div', 'style="width:100%; background:#e2e8f0; height:8px; border-radius:4px; overflow:hidden;"',
      tag('div', 'style="width:' + s.val + '%; background:#4f46e5; height:8px;"', '')
    )
  )
).join('');

const evidenceRows = (Array.isArray(dossier.verified_evidence_log) ? dossier.verified_evidence_log : []).map(ev => 
  tag('tr', '',
    tag('td', 'style="padding:8px; border-bottom:1px solid #e2e8f0;"', tag('strong', '', ev.claim_or_topic || '')) +
    tag('td', 'style="padding:8px; border-bottom:1px solid #e2e8f0;"', (ev.source_type || '') + selfTag('br', '') + tag('span', 'style="font-size:11px; color:#64748b;"', ev.evidence_date || '')) +
    tag('td', 'style="padding:8px; border-bottom:1px solid #e2e8f0;"', tag('a', 'href="' + (ev.source_url || baseInfo.company_url) + '" target="_blank" style="color:#4f46e5; text-decoration:none; font-weight:600;"', (ev.source_title || 'Verify Source Link') + ' ->'))
  )
).join('');

const cssStyles = '@page { size: A4; margin: 14mm; } ' +
  'body { font-family: -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica, Arial, sans-serif; color: #1e293b; line-height: 1.55; max-width: 860px; margin: 0 auto; padding: 20px; background: #ffffff; } ' +
  '.no-print-bar { background: #0f172a; color: #ffffff; padding: 14px 20px; border-radius: 8px; margin-bottom: 24px; display: flex; justify-content: space-between; align-items: center; } ' +
  '.print-btn { background: #4f46e5; color: #ffffff; border: none; padding: 10px 18px; border-radius: 6px; font-weight: 600; cursor: pointer; font-size: 14px; } ' +
  '.header-box { display: flex; align-items: center; justify-content: space-between; border-bottom: 3px solid #4f46e5; padding-bottom: 16px; margin-bottom: 20px; } ' +
  '.logo-img { width: 64px; height: 64px; object-fit: contain; border-radius: 12px; border: 1px solid #e2e8f0; padding: 6px; background: #fff; } ' +
  'h1 { color: #0f172a; margin: 0 0 6px 0; font-size: 26px; } ' +
  '.meta { font-size: 13px; color: #475569; } ' +
  'h2 { color: #3730a3; font-size: 17px; margin-top: 24px; margin-bottom: 10px; border-bottom: 1px solid #e2e8f0; padding-bottom: 6px; page-break-after: avoid; } ' +
  '.card { background: #f8fafc; padding: 14px 18px; border-radius: 8px; border-left: 4px solid #4f46e5; margin-bottom: 14px; page-break-inside: avoid; } ' +
  '.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; align-items: center; margin-bottom: 18px; page-break-inside: avoid; } ' +
  '.grid-4 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-bottom: 18px; page-break-inside: avoid; } ' +
  '.visual-box { border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px; text-align: center; background: #ffffff; page-break-inside: avoid; } ' +
  'ul, ol { margin-top: 6px; padding-left: 22px; } ' +
  '@media print { .no-print-bar { display: none !important; } body { padding: 0; } }';

const bodyContent = 
  tag('div', 'class="no-print-bar"',
    tag('span', '', tag('strong', '', 'Visual PDF Dossier Ready: ') + 'Includes Charts, Mermaid Diagrams, Images and Citations.') +
    tag('button', 'class="print-btn" onclick="window.print()"', 'Download / Save as PDF')
  ) +
  tag('div', 'class="header-box"',
    tag('div', '',
      tag('h1', '', 'Interview Intelligence Dossier: ' + baseInfo.company_name) +
      tag('div', 'class="meta"',
        tag('strong', '', 'Target Role: ') + baseInfo.target_role + ' | ' +
        tag('strong', '', 'Website: ') + tag('a', 'href="' + baseInfo.company_url + '"', baseInfo.company_url) + ' (' + baseInfo.url_resolution_mode + ') | ' +
        tag('strong', '', 'Date: ') + generatedDate
      )
    ) +
    selfTag('img', 'class="logo-img" src="' + baseInfo.company_logo + '" alt="Logo"')
  ) +
  tag('div', 'class="grid-4"', metricsHtml) +
  tag('h2', '', '1. Graphical Company Benchmark and Live Web Snapshot') +
  tag('div', 'class="grid-2"',
    tag('div', 'class="visual-box"',
      selfTag('img', 'src="' + radarChartUrl + '" style="width:100%; max-width:360px; height:auto;" alt="Company Radar Chart"') +
      tag('div', 'style="text-align:left; margin-top:10px;"', barsHtml)
    ) +
    tag('div', 'class="visual-box"',
      tag('div', 'style="font-size:12px; font-weight:600; color:#475569; margin-bottom:8px;"', 'Official Homepage Snapshot (' + baseInfo.company_domain + ')') +
      selfTag('img', 'src="' + baseInfo.website_screenshot + '" style="width:100%; border-radius:6px; border:1px solid #cbd5e1;" alt="Website Snapshot"') +
      tag('div', 'style="font-size:12px; color:#334155; text-align:left; margin-top:12px;"', tag('strong', '', 'Executive Summary: ') + (dossier.about_the_company || ''))
    )
  ) +
  tag('h2', '', '2. Product, Architecture and Ecosystem Diagram') +
  tag('div', 'class="visual-box" style="margin-bottom:16px;"',
    selfTag('img', 'src="' + mermaidImgUrl + '" style="max-width:100%; max-height:260px; height:auto;" alt="Architecture Diagram"')
  ) +
  tag('h2', '', '3. Mission, Vision and Cultural Values') +
  tag('div', 'class="card"', dossier.mission_vision_and_values || '') +
  tag('h2', '', '4. Flagship Projects, Products and Engineering Initiatives') +
  tag('ul', '', renderList(dossier.flagship_projects_and_products)) +
  tag('h2', '', '5. Recent Momentum and Strategic News (Last 6 Months)') +
  tag('ul', '', renderList(dossier.recent_momentum_and_news)) +
  tag('h2', '', '6. Tech Stack and Engineering Culture') +
  tag('div', 'class="card"', dossier.tech_stack_and_engineering_culture || '') +
  tag('h2', '', '7. Role Alignment and How to Pitch Yourself') +
  tag('ul', '', renderList(dossier.interview_talking_points_and_strategy)) +
  tag('h2', '', '8. Predicted and Reverse Interview Questions') +
  tag('div', 'class="grid-2" style="align-items:start;"',
    tag('div', 'class="card"', tag('strong', '', 'Questions They Will Likely Ask You:') + tag('ol', '', renderList(dossier.predicted_interview_questions))) +
    tag('div', 'class="card"', tag('strong', '', 'Insider Questions to Ask Them:') + tag('ol', '', renderList(dossier.reverse_interview_questions)))
  ) +
  tag('h2', '', '9. Verified Proofs and Evidence Log (Clickable Citations)') +
  tag('table', 'style="width:100%; border-collapse:collapse; font-size:12px; margin-top:8px; page-break-inside:avoid;"',
    tag('thead', '',
      tag('tr', 'style="background:#f1f5f9; text-align:left;"',
        tag('th', 'style="padding:8px; border-bottom:2px solid #cbd5e1;"', 'Verified Claim / Topic') +
        tag('th', 'style="padding:8px; border-bottom:2px solid #cbd5e1;"', 'Source and Date') +
        tag('th', 'style="padding:8px; border-bottom:2px solid #cbd5e1;"', 'Direct Proof Link')
      )
    ) +
    tag('tbody', '', evidenceRows)
  ) +
  tag('script', '', 'window.onload = function() { setTimeout(function() { window.print(); }, 1800); };');

const printableDocumentHtml = O + '!DOCTYPE html' + C +
  tag('html', '',
    tag('head', '',
      selfTag('meta', 'charset="utf-8"') +
      tag('title', '', baseInfo.company_name + ' - Visual Interview Research Dossier') +
      tag('style', '', cssStyles)
    ) +
    tag('body', '', bodyContent)
  );

return [{
  json: {
    company_name: baseInfo.company_name,
    company_url: baseInfo.company_url,
    target_role: baseInfo.target_role,
    file_name: safeFileName,
    radar_chart_url: radarChartUrl,
    mermaid_diagram_url: mermaidImgUrl,
    structured_dossier: dossier,
    printable_html_document: printableDocumentHtml
  }
}];
